-- KUEDU2IMPACT: กิจกรรมของแต่ละสถาบันในเครือข่ายวิจัยนานาชาติ (network-international.php และ network-partner.php)
--   network_activities = หนึ่งแถวต่อหนึ่งกิจกรรม (ช่วงเวลา ทิศทาง ข้อความ) ผูกกับ network_partners
--   network_photos     = เพิ่ม activity_id (รูปนี้มาจากกิจกรรมไหน) และ in_strip (แสดงในแถบภาพเลื่อนหรือไม่)
-- ข้อมูลจากเอกสารฝ่ายวิเทศสัมพันธ์ คณะศึกษาศาสตร์: 31 กิจกรรม 59 รูป (รูปอยู่ใน assets/images/network/ ต้องอัปโหลดก่อน)
-- เพิ่ม 5 สถาบันใหม่ (ผู้เชี่ยวชาญที่มาเยือนคณะ) และ AsTEN (เครือข่าย 10 ประเทศ รหัส XA ไม่ปักบนแผนที่)
-- phpMyAdmin → e2imedu → Import ใช้ได้ทั้ง MySQL 8 และ MariaDB 10.x
-- รันหลัง 2026-11-16-01, 02, 03 (และ 04 ถ้าเคยรัน ไฟล์นี้แก้คำบรรยายรูปชุดนั้นให้ตรงกิจกรรม)
-- รันซ้ำได้: สร้าง/เพิ่มเฉพาะที่ยังไม่มี ไม่ลบแถวใด ไม่ทับรูปที่เลือกเองใน admin (แถวที่มี image_id)
SET NAMES utf8mb4;
SET @db = DATABASE();

-- 1. ตารางกิจกรรม
CREATE TABLE IF NOT EXISTS network_activities (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  partner_id  INT UNSIGNED NOT NULL COMMENT 'สถาบัน: network_partners.id',
  direction   VARCHAR(10) CHARACTER SET ascii NOT NULL DEFAULT 'joint' COMMENT 'outbound = คณะไปเยือน, inbound = มาเยือนคณะ, joint = ทำร่วมกัน',
  period      VARCHAR(100) NULL COMMENT 'ช่วงเวลาแบบที่แสดงบนเว็บ เช่น 15–22 พ.ย. 2568 หรือ ก.ย. ทุกปี',
  title       VARCHAR(200) NOT NULL COMMENT 'ชื่อกิจกรรมสั้น ๆ แสดงบนรูปเมื่อชี้และเป็นหัวข้อในไทม์ไลน์',
  body        TEXT NULL COMMENT 'รายละเอียดกิจกรรม',
  is_public   TINYINT(1) NOT NULL DEFAULT 1 COMMENT '1 = แสดง, 0 = ซ่อน',
  sort_order  INT NOT NULL DEFAULT 0 COMMENT 'ลำดับในหน้าสถาบัน (น้อยขึ้นก่อน)',
  KEY idx_activity_partner (partner_id),
  CONSTRAINT fk_network_activities_partner FOREIGN KEY (partner_id) REFERENCES network_partners (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='กิจกรรมกับสถาบันในเครือข่ายวิจัยนานาชาติ';

-- ตาราง network_photos (เหมือน 2026-11-16-03 เผื่อยังไม่ได้ Import)
CREATE TABLE IF NOT EXISTS network_photos (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  image_id    INT UNSIGNED NULL COMMENT 'รูป: เลข id ในตาราง media',
  image       VARCHAR(255) NULL COMMENT 'รูปแบบเดิม (path) ใช้เมื่อ image_id ว่าง',
  caption     VARCHAR(300) NOT NULL COMMENT 'คำบรรยายภาพ ใช้เป็นข้อความแทนภาพสำหรับโปรแกรมอ่านหน้าจอ',
  is_public   TINYINT(1) NOT NULL DEFAULT 1 COMMENT '1 = แสดง, 0 = ซ่อน',
  sort_order  INT NOT NULL DEFAULT 0 COMMENT 'ลำดับ (น้อยขึ้นก่อน)',
  CONSTRAINT fk_network_photos_image FOREIGN KEY (image_id) REFERENCES media (id) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ภาพกิจกรรมกับเครือข่ายวิจัยนานาชาติ';

SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = @db AND TABLE_NAME = 'network_photos' AND COLUMN_NAME = 'activity_id') = 0,
  'ALTER TABLE network_photos ADD COLUMN activity_id INT UNSIGNED NULL COMMENT ''กิจกรรมที่รูปนี้มาจาก: network_activities.id'' AFTER id', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = @db AND TABLE_NAME = 'network_photos' AND COLUMN_NAME = 'in_strip') = 0,
  'ALTER TABLE network_photos ADD COLUMN in_strip TINYINT(1) NOT NULL DEFAULT 1 COMMENT ''1 = แสดงในแถบภาพเลื่อนใต้การ์ด, 0 = แสดงเฉพาะในหน้าสถาบัน'' AFTER is_public', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = IF((SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE TABLE_SCHEMA = @db AND TABLE_NAME = 'network_photos' AND CONSTRAINT_NAME = 'fk_network_photos_activity') = 0,
  'ALTER TABLE network_photos ADD CONSTRAINT fk_network_photos_activity FOREIGN KEY (activity_id) REFERENCES network_activities (id) ON DELETE SET NULL ON UPDATE CASCADE', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- 2. สถาบันใหม่ 5 แห่ง (ผู้เชี่ยวชาญที่มาเยือนคณะ) และ AsTEN
