INSERT INTO network_partners (country_code, country_name_th, institution, tags, summary, people, url, is_public, sort_order) SELECT 'AU', 'ออสเตรเลีย', 'University of Canberra', 'visiting-scholar', 'ผู้เชี่ยวชาญรับเชิญที่มาเป็นวิทยากร จัด workshop และให้คำปรึกษาด้านการวิจัยแก่คณะ', 'Adjunct Associate Professor Chris Morrissey', 'https://www.canberra.edu.au', 1, 230 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM network_partners WHERE institution = 'University of Canberra');
INSERT INTO network_partners (country_code, country_name_th, institution, tags, summary, people, url, is_public, sort_order) SELECT 'US', 'สหรัฐอเมริกา', 'Johns Hopkins University', 'visiting-scholar', 'ผู้เชี่ยวชาญรับเชิญที่มาเป็นวิทยากร จัด workshop และให้คำปรึกษาด้านการวิจัยแก่คณะ', 'Dr. Cecilia Chen', 'https://www.jhu.edu', 1, 240 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM network_partners WHERE institution = 'Johns Hopkins University');
INSERT INTO network_partners (country_code, country_name_th, institution, tags, summary, people, url, is_public, sort_order) SELECT 'CA', 'แคนาดา', 'University of Victoria', 'visiting-scholar', 'ผู้เชี่ยวชาญรับเชิญที่มาเป็นวิทยากร จัด workshop และให้คำปรึกษาด้านการวิจัยแก่คณะ', 'Ms. Rena Fowler', 'https://www.uvic.ca', 1, 250 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM network_partners WHERE institution = 'University of Victoria');
INSERT INTO network_partners (country_code, country_name_th, institution, institution_th, tags, summary, url, image, is_public, sort_order) SELECT 'XA', 'อาเซียน', 'Association of Southeast Asian Teacher Education Network (AsTEN)', 'เครือข่ายสถาบันผลิตครูอาเซียน', 'research,exchange,conference', 'คณะเป็นสถาบันในเครือข่ายสถาบันผลิตครูชั้นนำของ 10 ประเทศอาเซียน ทำงานร่วมกันทั้งประกันคุณภาพหลักสูตร วารสาร ประชุมวิชาการ และแลกเปลี่ยนนักศึกษา', NULL, 'assets/images/network/asten-02.webp', 1, 260 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM network_partners WHERE institution = 'Association of Southeast Asian Teacher Education Network (AsTEN)');

-- ผู้เชี่ยวชาญที่มาเยือนจากสถาบันที่มีอยู่แล้ว: เพิ่มชื่อถ้ายังไม่มี
UPDATE network_partners SET people = IF(people IS NULL OR people = '', 'Professor Kennedy Chan', CONCAT(people, ', ', 'Professor Kennedy Chan')) WHERE institution = 'The University of Hong Kong' AND (people IS NULL OR people NOT LIKE '%Professor Kennedy Chan%');
UPDATE network_partners SET people = IF(people IS NULL OR people = '', 'Professor Arlyne Marasigan', CONCAT(people, ', ', 'Professor Arlyne Marasigan')) WHERE institution = 'Philippine Normal University (PNU)' AND (people IS NULL OR people NOT LIKE '%Professor Arlyne Marasigan%');
UPDATE network_partners SET tags = CONCAT(tags, ',visiting-scholar') WHERE institution = 'The University of Hong Kong' AND FIND_IN_SET('visiting-scholar', tags) = 0;
UPDATE network_partners SET summary = 'Professor Kennedy Chan มาเป็นวิทยากรรับเชิญและให้คำปรึกษาด้านการวิจัยแก่คณะ' WHERE institution = 'The University of Hong Kong' AND (summary IS NULL OR summary = '');

-- 3. กิจกรรม 31 รายการ (จับคู่สถาบันด้วยชื่อ institution)
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'inbound', '30 ก.ค. 2568', 'นักศึกษาบัณฑิตศึกษาจาก Konkuk เยือนคณะ', 'คณะผู้บริหาร คณาจารย์ และนักศึกษาจาก Konkuk University พานิสิตระดับบัณฑิตศึกษา 26 คน มาทำกิจกรรมแลกเปลี่ยนที่คณะศึกษาศาสตร์ และเยี่ยมชมโรงเรียนสาธิตแห่งมหาวิทยาลัยเกษตรศาสตร์', 1, 0 FROM network_partners p WHERE p.institution = 'Konkuk University' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'นักศึกษาบัณฑิตศึกษาจาก Konkuk เยือนคณะ') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'outbound', '15–22 พ.ย. 2568', 'นิสิตบัณฑิตศึกษาแลกเปลี่ยนระยะสั้นที่ Konkuk', 'นิสิตระดับบัณฑิตศึกษาไปแลกเปลี่ยนระยะสั้นที่ Konkuk University ประเทศเกาหลีใต้ ด้วยทุนเสริมสร้างศักยภาพนิสิต มก. สู่สากล ประจำปี 2568', 1, 10 FROM network_partners p WHERE p.institution = 'Konkuk University' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'นิสิตบัณฑิตศึกษาแลกเปลี่ยนระยะสั้นที่ Konkuk') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'joint', '15 ต.ค. 2569', 'ศึกษาปฐมวัยและลงนาม MOU กับ KSECE', 'นิสิตปริญญาเอก สาขาวิชาปฐมวัยศึกษา แลกเปลี่ยนเรียนรู้เรื่องการจัดการศึกษาปฐมวัย และคณะลงนามบันทึกความเข้าใจกับ Korean Society for Early Childhood Education (KSECE) ซึ่งมีอาจารย์จาก Konkuk University เป็นนายกสมาคม', 1, 20 FROM network_partners p WHERE p.institution = 'Konkuk University' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'ศึกษาปฐมวัยและลงนาม MOU กับ KSECE') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'joint', NULL, 'วิจัยเปรียบเทียบหลักสูตรคณิตศาสตร์ปฐมวัย', 'ศิษย์เก่าของ Konkuk University ทำวิจัยร่วมกับ รศ.ดร.ชลาธิป สมาหิโต และ ผศ.ดร.วันดี เกษมสุขพิพัฒน์ เปรียบเทียบหลักสูตรคณิตศาสตร์ปฐมวัยของสหรัฐอเมริกา ไทย และเกาหลีใต้', 1, 30 FROM network_partners p WHERE p.institution = 'Konkuk University' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'วิจัยเปรียบเทียบหลักสูตรคณิตศาสตร์ปฐมวัย') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'outbound', 'ก.พ. และ ก.ค. ทุกปี', 'นิสิตบัณฑิตศึกษาในโครงการ TWINCLE ที่ Chiba', 'นิสิตระดับบัณฑิตศึกษาเข้าร่วมโครงการ TWINCLE Program ที่ Chiba University ด้วยทุน JASSO รวมถึง Sakura Program และ Physics Program', 1, 40 FROM network_partners p WHERE p.institution = 'Chiba University' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'นิสิตบัณฑิตศึกษาในโครงการ TWINCLE ที่ Chiba') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'inbound', 'ก.ย. ทุกปี 10–15 วัน', 'นักศึกษาจาก Chiba ทำกิจกรรมที่คณะ', 'นักศึกษาจาก Chiba University มาทำกิจกรรมที่คณะศึกษาศาสตร์ในเดือนกันยายนของทุกปี ครั้งละ 10–15 วัน', 1, 50 FROM network_partners p WHERE p.institution = 'Chiba University' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'นักศึกษาจาก Chiba ทำกิจกรรมที่คณะ') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'outbound', NULL, 'นิสิตไปทำกิจกรรมที่ Kyoai Gakuen', 'คณะพานิสิตแลกเปลี่ยนไปทำกิจกรรมที่ Kyoai Gakuen University ด้วยทุนเสริมสร้างศักยภาพนิสิต มก. สู่สากล', 1, 60 FROM network_partners p WHERE p.institution = 'Kyoai Gakuen University' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'นิสิตไปทำกิจกรรมที่ Kyoai Gakuen') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'inbound', 'ส.ค.–ก.ย. ทุกปี', 'นักศึกษาจาก Kyoai Gakuen แลกเปลี่ยนที่คณะ', 'นักศึกษาจาก Kyoai Gakuen University มาทำกิจกรรมแลกเปลี่ยนที่คณะศึกษาศาสตร์ มก. ในช่วงเดือนสิงหาคมถึงกันยายนของทุกปี', 1, 70 FROM network_partners p WHERE p.institution = 'Kyoai Gakuen University' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'นักศึกษาจาก Kyoai Gakuen แลกเปลี่ยนที่คณะ') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'inbound', '1 ภาคการศึกษา', 'นักศึกษาจาก Kyoai Gakuen เป็นนิสิตแลกเปลี่ยนผ่าน KUOSSP', 'นักศึกษาจาก Kyoai Gakuen University มาเป็นนิสิตแลกเปลี่ยนหนึ่งภาคการศึกษา ด้วยทุน KUOSSP (Kasetsart University One Semester Package Programs)', 1, 80 FROM network_partners p WHERE p.institution = 'Kyoai Gakuen University' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'นักศึกษาจาก Kyoai Gakuen เป็นนิสิตแลกเปลี่ยนผ่าน KUOSSP') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'outbound', NULL, 'นิสิตร่วมโครงการ Campus Asia', 'นิสิตคณะศึกษาศาสตร์เข้าร่วมโครงการ Campus Asia ที่จัดโดย Hiroshima University, Changchun University และ Beijing Normal University', 1, 90 FROM network_partners p WHERE p.institution = 'Hiroshima University' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'นิสิตร่วมโครงการ Campus Asia') LIMIT 1;
