INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'outbound', '1 ภาคการศึกษา', 'นิสิตได้ทุนแลกเปลี่ยนที่ NIE สิงคโปร์', 'นิสิตคณะศึกษาศาสตร์ได้ทุน NIE Singapore ASEAN Undergraduate Scholarship ไปแลกเปลี่ยนที่ National Institute of Education สิงคโปร์ หนึ่งภาคการศึกษา', 1, 120 FROM network_partners p WHERE p.institution = 'National Institute of Education (NIE), Nanyang Technological University' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'นิสิตได้ทุนแลกเปลี่ยนที่ NIE สิงคโปร์') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'joint', NULL, 'นิสิตได้ทุนเรียน NIE Undergraduate Online Program', 'นิสิตคณะศึกษาศาสตร์ได้ทุนเรียน NIE Singapore Undergraduate Online Program', 1, 130 FROM network_partners p WHERE p.institution = 'National Institute of Education (NIE), Nanyang Technological University' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'นิสิตได้ทุนเรียน NIE Undergraduate Online Program') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'inbound', NULL, 'Dr. Tang Wee บรรยายการวิเคราะห์ข้อมูลเชิงคุณภาพ', 'คณะเชิญ Dr. Tang Wee มาบรรยายพิเศษเรื่องการวิเคราะห์ข้อมูลเชิงคุณภาพ ให้นักวิจัยและนิสิตระดับบัณฑิตศึกษา', 1, 140 FROM network_partners p WHERE p.institution = 'National Institute of Education (NIE), Nanyang Technological University' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'Dr. Tang Wee บรรยายการวิเคราะห์ข้อมูลเชิงคุณภาพ') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'inbound', NULL, 'ภาควิชาพลศึกษาต้อนรับผู้บริหารและนักศึกษาจาก NIE', 'ภาควิชาพลศึกษา คณะศึกษาศาสตร์ มก. ต้อนรับผู้บริหารและนักศึกษาจาก NIE สาธารณรัฐสิงคโปร์', 1, 150 FROM network_partners p WHERE p.institution = 'National Institute of Education (NIE), Nanyang Technological University' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'ภาควิชาพลศึกษาต้อนรับผู้บริหารและนักศึกษาจาก NIE') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'inbound', '1 ธ.ค. 2568', 'นักศึกษาจาก USSH ร่วมกิจกรรมแลกเปลี่ยนที่คณะ', 'คณะศึกษาศาสตร์จัดกิจกรรมแลกเปลี่ยนหนึ่งวันให้นักศึกษาจาก USSH ซึ่งเป็นสถาบันในเครือข่าย AsTEN', 1, 160 FROM network_partners p WHERE p.institution = 'University of Social Sciences and Humanities, Vietnam National University, Hanoi (USSH)' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'นักศึกษาจาก USSH ร่วมกิจกรรมแลกเปลี่ยนที่คณะ') LIMIT 1;
