INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'inbound', '1 เดือน', 'นิสิตจาก PNU ฝึกประสบการณ์วิชาชีพที่โรงเรียนเครือข่าย', 'โครงการ EDU KU–PNU–UIC Teaching Practicum Exchange รับนิสิตจาก PNU มาฝึกประสบการณ์วิชาชีพที่โรงเรียนเครือข่ายหนึ่งเดือน ด้วยทุนเสริมสร้างศักยภาพนิสิต มก. สู่สากล', 1, 180 FROM network_partners p WHERE p.institution = 'Philippine Normal University (PNU)' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'นิสิตจาก PNU ฝึกประสบการณ์วิชาชีพที่โรงเรียนเครือข่าย') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'outbound', '1 เดือน', 'นิสิตแลกเปลี่ยนในโครงการ AsTEN STEP', 'นิสิตคณะศึกษาศาสตร์ไปแลกเปลี่ยนหนึ่งเดือนในโครงการ AsTEN STEP ด้วยทุนเสริมสร้างศักยภาพนิสิต มก. สู่สากล', 1, 190 FROM network_partners p WHERE p.institution = 'Philippine Normal University (PNU)' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'นิสิตแลกเปลี่ยนในโครงการ AsTEN STEP') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'inbound', NULL, 'Prof. Scott Ashmann เป็น Visiting Professor', 'Prof. Dr. Scott Ashmann มาเป็น Visiting Professor ที่คณะศึกษาศาสตร์ และบรรยายเรื่อง Issues and Trends in Environmental Education', 1, 200 FROM network_partners p WHERE p.institution = 'University of Wisconsin–Green Bay (UWGB)' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'Prof. Scott Ashmann เป็น Visiting Professor') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'inbound', NULL, 'นักศึกษาจาก UWGB ฝึกประสบการณ์วิชาชีพที่โรงเรียนสาธิต มก.', 'นักศึกษาจาก UWGB มาฝึกประสบการณ์วิชาชีพที่โรงเรียนสาธิตแห่งมหาวิทยาลัยเกษตรศาสตร์ โครงการการศึกษานานาชาติ', 1, 210 FROM network_partners p WHERE p.institution = 'University of Wisconsin–Green Bay (UWGB)' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'นักศึกษาจาก UWGB ฝึกประสบการณ์วิชาชีพที่โรงเรียนสาธิต มก.') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'inbound', '17–28 พ.ย. 2569', 'Prof. Mary Earick เป็น Visiting Professor และ Keynote', 'คณะเชิญ Prof. Mary Earick มาเป็น Visiting Professor และเป็น Keynote Speaker ในงาน CU-KU Joint International Conference in Education 2026', 1, 220 FROM network_partners p WHERE p.institution = 'Northern Illinois University (NIU)' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'Prof. Mary Earick เป็น Visiting Professor และ Keynote') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'joint', '5 พ.ย. 2569', 'นำเสนอผลงานที่ Council on Thai Studies 2026', 'รศ.ดร.ชาตรี ฝ่ายคำตา ผศ.ดร.วันดี เกษมสุขพิพัฒน์ และนิสิตบัณฑิตศึกษา นายนครินทร์ จันทะโส นำเสนอผลงานแบบออนไลน์ในงาน 2026 Annual Council on Thai Studies Meeting จัดโดย Center for Southeast Asian Studies, NIU', 1, 230 FROM network_partners p WHERE p.institution = 'Northern Illinois University (NIU)' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'นำเสนอผลงานที่ Council on Thai Studies 2026') LIMIT 1;
