INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'inbound', NULL, 'คณาจารย์จาก NDHU มาเยือนและเจรจาความร่วมมือ', 'คณะศึกษาศาสตร์ต้อนรับคณาจารย์จาก National Dong Hwa University ที่มาเยือนและเจรจาความร่วมมือระหว่างสองสถาบัน', 1, 260 FROM network_partners p WHERE p.institution = 'National Dong Hwa University (NDHU)' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'คณาจารย์จาก NDHU มาเยือนและเจรจาความร่วมมือ') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'inbound', NULL, 'Prof. Te-Sheng Chang บรรยายเรื่องความเท่าเทียมในการศึกษา', 'Prof. Te-Sheng Chang จาก NDHU บรรยายพิเศษหัวข้อ Promoting Equality in Education: Key Gender Issues and Policy Insights from Taiwan ให้นิสิตและคณาจารย์คณะศึกษาศาสตร์', 1, 270 FROM network_partners p WHERE p.institution = 'National Dong Hwa University (NDHU)' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'Prof. Te-Sheng Chang บรรยายเรื่องความเท่าเทียมในการศึกษา') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'inbound', '2567', 'นิสิตปริญญาเอกจาก NDHU แลกเปลี่ยนวิจัย iIREP 2024', 'คณะรับนิสิตปริญญาเอกจาก NDHU มาแลกเปลี่ยนด้วยทุน International Internship Research Exchange Program 2024 (iIREP 2024)', 1, 280 FROM network_partners p WHERE p.institution = 'National Dong Hwa University (NDHU)' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'นิสิตปริญญาเอกจาก NDHU แลกเปลี่ยนวิจัย iIREP 2024') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'outbound', NULL, 'คณาจารย์ของคณะเป็น Keynote Speaker ที่ NDHU', 'NDHU เชิญคณาจารย์จากคณะศึกษาศาสตร์ไปเป็น Keynote Speaker และบรรยายให้นิสิตระดับบัณฑิตศึกษา', 1, 290 FROM network_partners p WHERE p.institution = 'National Dong Hwa University (NDHU)' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'คณาจารย์ของคณะเป็น Keynote Speaker ที่ NDHU') LIMIT 1;
INSERT INTO network_activities (partner_id, direction, period, title, body, is_public, sort_order) SELECT p.id, 'joint', NULL, 'กิจกรรมร่วมในเครือข่าย AsTEN', 'คณะศึกษาศาสตร์ทำงานร่วมกับสถาบันในเครือข่าย AsTEN หลายด้าน เพื่อขับเคลื่อนการผลิตครูในภูมิภาคอาเซียน เช่น ระบบประกันคุณภาพหลักสูตรผลิตครูอาเซียน (ATQA) วารสาร AsTEN Journal การประชุมวิชาการนานาชาติ และการแลกเปลี่ยนนักศึกษา', 1, 300 FROM network_partners p WHERE p.institution = 'Association of Southeast Asian Teacher Education Network (AsTEN)' AND NOT EXISTS (SELECT 1 FROM network_activities a WHERE a.partner_id = p.id AND a.title = 'กิจกรรมร่วมในเครือข่าย AsTEN') LIMIT 1;

